-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الفاعل وأحكامه","passage":"في «رسمَ الطالبُ الشكلَ» «الطالبُ» فاعل مرفوع بالضمة و«الشكلَ» مفعول به منصوب. قد يكون الفاعل اسمًا ظاهرًا أو ضميرًا، وقد يتأخر عن المفعول في تراكيب لها ضوابط. نحلل علاقة الفعل بمن أسند إليه قبل وضع العلامة الإعرابية.","prompt":"ما إعراب «الطالبُ» في «رسم الطالب الشكل»؟","correct":"فاعل مرفوع","w1":"مبتدأ مرفوع","w2":"مفعول به","w3":"خبر كان","practice":"أعرب ست جمل فعلية مختلفة، وحدد الفاعل الظاهر أو الضمير وعلامة رفعه."},{"n":2,"skill":"تجريد الفعل من علامة التثنية والجمع","passage":"في العربية الفصحى الشائعة نقول «جاء الطالبان» لا «جاءا الطالبان» في البناء المعتاد حين يتأخر الفاعل الظاهر، بينما في «الطالبان جاءا» تظهر ألف الاثنين في الفعل المسند إلى ضمير. تراجع أمثلة ما يسمى لغة «أكلوني البراغيث» في سياقها النحوي دون تعميم.","prompt":"أي تركيب هو الأشهر حين يتأخر الفاعل المثنى الظاهر؟","correct":"جاء الطالبان","w1":"جاءا الطالبان","w2":"جاءون الطالبان","w3":"جاء الطالبونان","practice":"وازن بين أربع جمل يتقدم فيها الفعل وأخرى يتقدم فيها المبتدأ، ثم بين علامات الإسناد."},{"n":3,"skill":"حذف الفعل جوازًا أو وجوبًا","passage":"قد يحذف الفعل في تراكيب يدل عليها السياق أو باب نحوي خاص، مثل الاستجابة المختصرة عن سؤال «مَن حضر؟» بقول «محمدٌ» على تقدير «حضر محمدٌ» بحسب التحليل. يتغير حكم الحذف بين الجواز والوجوب وفق الباب، فلا يصح تعميم مثال واحد.","prompt":"ما الذي يجيز فهم الفعل المحذوف في جواب «محمد»؟","correct":"دلالة السؤال والسياق","w1":"وجود حرف جر","w2":"حذف الاسم كذلك","w3":"تثنية الكلمة","practice":"ابحث في شرح نحوي موثوق عن موضع حذف جائز وآخر واجب، ثم اشرح القرينة والإعراب."},{"n":4,"skill":"ترتيب المفعول والفاعل","passage":"في «قرأَ خالدٌ الدرسَ» تقدّم الفاعل على المفعول، ويمكن «قرأَ الدرسَ خالدٌ» مع وضوح العلامات. وفي أمثلة أخرى يجب مراعاة الضمائر وحصر الفاعل والمفعول منعًا للبس. لا يُحكم على الموقع النحوي من ترتيب اللفظ وحده.","prompt":"ما المفعول به في «قرأ الدرس خالد»؟","correct":"الدرسَ","w1":"خالدٌ","w2":"قرأ","w3":"حرف الجر","practice":"أعد ترتيب خمس جمل مع الحفاظ على المعنى والإعراب ثم حدّد ما يجوز تقديمه وما قد يسبب لبسًا."},{"n":5,"skill":"علامات التأنيث في الاسم","passage":"من علامات التأنيث التاء المربوطة في «مدرسة»، والألف المقصورة في «حبلى»، والألف الممدودة في «صحراء»، لكن ليست جميع الأسماء المؤنثة مشتملة على علامة ظاهرة مثل «شمس». نفرق بين التأنيث اللفظي والمعنوي.","prompt":"ما علامة التأنيث في «صحراء»؟","correct":"الألف الممدودة","w1":"التاء المربوطة","w2":"ألف التثنية","w3":"ياء النسب","practice":"صنف اثني عشر اسمًا إلى مؤنث بعلامة ومؤنث بلا علامة مع أمثلة مقابلة."},{"n":6,"skill":"تثنية المقصور والمنقوص والممدود","passage":"في تثنية «فتى» نقول «فتيان» برد الألف إلى أصلها المناسب في هذا المثال، وفي «قاضٍ» نقول «قاضيان» عند الرفع، وتختلف معالجة الهمزة في بعض الأسماء الممدودة بحسب أصلها. يلزم الرجوع إلى بنية الاسم لا حفظ نهاية واحدة.","prompt":"ما تثنية «قاضٍ» في حالة الرفع؟","correct":"قاضيان","w1":"قاضان","w2":"قاضيات","w3":"قاضون","practice":"ثن خمسة أسماء مقصورة ومنقوصة وممدودة في ثلاث حالات إعرابية مع بيان السبب."},{"n":7,"skill":"فصاحة الكلمة والكلام","passage":"تتعلق فصاحة الكلمة بسلامتها من بعض العيوب مثل تنافر الحروف أو غرابة موحشة بحسب مقامها، وتتناول فصاحة الكلام حسن التركيب وخلوه من تعقيد يفسد الفهم. قد تكون الكلمات مألوفة لكن الجملة غامضة بسبب ترتيبها.","prompt":"ما المستوى الذي يتناول وضوح ترتيب الألفاظ؟","correct":"فصاحة الكلام","w1":"وزن البحر الشعري","w2":"إعراب المثنى وحده","w3":"عدد الحروف","practice":"اكتب جملتين غامضتين ثم أعد صياغتهما بصورة فصيحة وفسر موضع التحسين."},{"n":8,"skill":"مطابقة الكلام لمقتضى الحال","passage":"«العملُ منظمٌ» خبر بسيط يناسب من لا يحتاج إلى توكيد، و«إنَّ العملَ منظمٌ» يستعمل أداة توكيد حين يقتضي السياق ذلك. تقاس بلاغة العبارة بملاءمتها لحال المتلقي والهدف، لا بكثرة الزخارف وحدها.","prompt":"متى يكون التوكيد مناسبًا أكثر؟","correct":"عند وجود شك لدى المخاطب","w1":"في كل جملة دون تمييز","w2":"عند غياب المعنى","w3":"بعد كل فعل أمر","practice":"صغ خبرًا واحدًا بثلاث صيغ تناسب مخاطبًا خالي الذهن وشاكًا ومنكرًا، مع تفسير الاختيار."},{"n":9,"skill":"بناء الفعل للمجهول ونائب الفاعل","passage":"«أنجزَ العاملُ المشروعَ» مبني للمعلوم، و«أُنجِزَ المشروعُ» مبني للمجهول مع نائب فاعل مرفوع. تختلف حركة الفعل الماضي في التحويل، وقد يتغير بناء المضارع وفق قاعدته، ويتغير مركز الاهتمام من الفاعل إلى الحدث أو أثره.","prompt":"ما إعراب «المشروعُ» في «أُنجز المشروعُ»؟","correct":"نائب فاعل مرفوع","w1":"مفعول به منصوب","w2":"فاعل ظاهر","w3":"مضاف إليه","practice":"حوّل خمس جمل من المعلوم إلى المجهول واضبط الفعل ونائب الفاعل مع شرح سبب الحذف."},{"n":10,"skill":"ما ينوب عن الفاعل","passage":"إذا بُني الفعل للمجهول قد ينوب عن الفاعل المفعول به كما في «كُتِبَ الدرسُ»، وفي أحوال محددة قد ينوب غيره وفق الضوابط النحوية عند غياب المفعول به. يلزم الرجوع إلى باب النائب وعدم جعل كل جار ومجرور نائبًا بلا شروط.","prompt":"ما نائب الفاعل في «كُتب الدرسُ»؟","correct":"الدرسُ","w1":"الكاف","w2":"الفاعل المحذوف","w3":"فعل كتب","practice":"حلل ست جمل مبنية للمجهول وبيّن العنصر الذي ناب عن الفاعل وعلامة إعرابه."},{"n":11,"skill":"الفعل اللازم والمتعدي","passage":"«جلسَ الطفلُ» يكتفي بفاعله في هذا التركيب، و«قرأَ الطفلُ القصةَ» يتعدى إلى مفعول به. يمكن أن يرتبط اللازم بحرف جر يؤدي معنى إضافيًا مثل «ذهب إلى المدرسة» من دون أن يصبح الاسم المجرور مفعولًا به منصوبًا.","prompt":"أي فعل متعد إلى مفعول به في المثال؟","correct":"قرأ القصة","w1":"جلس الطفل","w2":"ذهب إلى البيت","w3":"نام الطفل","practice":"صنف عشرة أفعال في تراكيب واضحة إلى لازم ومتعد، ثم جرب إضافة جار ومجرور إلى بعضها."},{"n":12,"skill":"جمع التكسير وتغير البناء","passage":"«كتاب» يجمع على «كتب»، فتتغير صورة المفرد في جمع التكسير، بخلاف جمع المذكر السالم مثل «عاملون» الذي يحافظ على بنية المفرد مع الزيادة. ليست كل كلمة تنتهي بألف وتاء جمع مؤنث سالمًا بالضرورة.","prompt":"ما جمع التكسير لكلمة «كتاب»؟","correct":"كتب","w1":"كاتبون","w2":"كتابان","w3":"كتابيات","practice":"اكتب عشرة جموع تكسير من ألفاظ صحيحة، وقارنها بأمثلة للجمع السالم من حيث البناء."},{"n":13,"skill":"جموع القلة في الأوزان المشهورة","passage":"من أوزان جموع القلة المشهورة «أَفْعُل» و«أَفْعَال» و«أَفْعِلَة» و«فِعْلَة»، مثل «أقلام» على وزن «أفعال». وقد يستعمل جمع القلة للكثرة بحسب السياق، فلا نحكم على العدد بمجرد الوزن.","prompt":"ما وزن «أقلام» الصرفي؟","correct":"أفعال","w1":"مفاعيل","w2":"فعول","w3":"فواعل","practice":"هات مثالين لكل وزن من أوزان جموع القلة الشائعة وفسر استعمالًا يتجاوز مدلول القلة."},{"n":14,"skill":"تمييز الخبر والإنشاء","passage":"«المكتبة مفتوحة» جملة خبرية تحتمل الصدق والكذب لذاتها، أما «افتح المكتبة» إنشاء طلبي لا يوصف في نفسه بذلك. يتحدد النوع من الصيغة والمعنى، مع إمكان خروج الجملة إلى أغراض بلاغية بحسب المقام.","prompt":"أي جملة إنشائية طلبية؟","correct":"افتح المكتبة","w1":"المكتبة مفتوحة","w2":"المعلم حاضر","w3":"التقرير جاهز","practice":"صنف عشر جمل إلى خبرية وإنشائية، واذكر الغرض البلاغي المحتمل في اثنتين."},{"n":15,"skill":"أغراض الخبر الحقيقية والمجازية","passage":"قد يكون الغرض الأصلي من الخبر إفادة المخاطب بالحكم أو إفادته أن المتكلم يعلم به، وقد يستعمل المدح أو الوعظ أو التحسر بحسب القرينة. قول «لقد فات الوقت» قد يكون خبرًا محضًا أو تعبيرًا عن الأسف في سياق آخر.","prompt":"ماذا يكشف الغرض البلاغي للخبر؟","correct":"السياق وحال المتكلم والمخاطب","w1":"عدد الأسماء وحده","w2":"علامة الجر","w3":"الوزن الصرفي","practice":"اكتب خبرًا واحدًا في ثلاثة سياقات مختلفة وناقش كيف يتغير غرضه البلاغي."},{"n":16,"skill":"أضرب الخبر ودرجة التوكيد","passage":"من التقسيم الدراسي للخبر: ابتدائي لا يحتاج إلى مؤكد في الأصل، وطلبي يؤكد لمخاطب متردد، وإنكاري يقوى توكيده بحسب درجة الإنكار. نميز حالة المخاطب قبل اختيار «إنّ» أو اللام أو القسم.","prompt":"ما الضرب المناسب لمخاطب ينكر الحكم؟","correct":"الخبر الإنكاري","w1":"الخبر الابتدائي دائمًا","w2":"الاستفهام فقط","w3":"النعت","practice":"أنشئ أمثلة لخبر ابتدائي وطلبي وإنكاري من مضمون واحد مع شرح الأدوات."},{"n":17,"skill":"الالتفات وتغيير جهة الخطاب","passage":"في الالتفات ينتقل التعبير بين التكلم والخطاب والغيبة لغرض بلاغي، مثل الانتقال من «أذكر صداقتي» إلى «فأنت يا صديقي تعرف قيمتها» إذا كان الانتقال مقصودًا ومناسبًا. ليس كل اضطراب في الضمائر التفاتًا حسنًا.","prompt":"ما السمة الظاهرة للالتفات؟","correct":"الانتقال المقصود بين ضمائر الخطاب","w1":"تكرار الفعل نفسه","w2":"استخدام المفعول المطلق","w3":"حذف جميع الضمائر","practice":"اكتب نصًا قصيرًا فيه التفات محسوب، ثم علل أثر الانتقال في توجيه الانتباه."},{"n":18,"skill":"المفعول المطلق وأنواعه","passage":"«انتصرَ الفريقُ انتصارًا» «انتصارًا» مفعول مطلق يؤكد الفعل، و«سارَ سيرًا سريعًا» يبين نوعه بوصف المصدر. يمكن أن يدل المفعول المطلق على العدد في صيغ مثل «دقّ الباب دقتين» بشروطه.","prompt":"ما وظيفة «انتصارًا» في المثال؟","correct":"مفعول مطلق مؤكد للفعل","w1":"مفعول به","w2":"حال","w3":"فاعل","practice":"أنشئ ست جمل تتوزع فيها أغراض المفعول المطلق على التأكيد والنوع والعدد."},{"n":19,"skill":"المفعول لأجله وشروطه","passage":"في «درستُ رغبةً في العلم» مصدر «رغبةً» يبين علة الدراسة إذا استوفت شروط المفعول لأجله، ومنها اتحاد الفاعل والزمان في المثال الشائع. لا يكفي نصب أي مصدر بعد فعل لجعله مفعولًا لأجله.","prompt":"ما الذي تبينه «رغبةً» في المثال؟","correct":"سبب الدراسة","w1":"عدد الدروس","w2":"مكان الدراسة","w3":"صفة الكتاب","practice":"كوّن ثلاث جمل بمفعول لأجله وأخرى بعبارة تعليل مجرورة، ثم فسّر الاختلاف."},{"n":20,"skill":"المفعول معه بعد واو المعية","passage":"في «سرتُ والنهرَ» يمكن أن تكون الواو للمعية ويُعرب «النهرَ» مفعولًا معه منصوبًا، في سياق يفيد المصاحبة لا مشاركة النهر في فعل السير. تختلف واو المعية عن واو العطف بحسب المعنى.","prompt":"ما إعراب «النهرَ» في «سرت والنهرَ» عند قصد المعية؟","correct":"مفعول معه منصوب","w1":"فاعل مرفوع","w2":"مبتدأ","w3":"بدل","practice":"اكتب جملًا تفرق فيها واو المعية من واو العطف، وبين قرينة كل تحليل."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=11
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='4611ec73-1e1a-4571-9c51-05d7c901c83f'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='نحو 211 — النحو والصرف والبلاغة' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الحادي عشر، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الحادي عشر%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G11_T1_NAHW211_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G11_T1_NAHW211_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G11_T1_NAHW211_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G11_T1_NAHW211_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;